      "keystrokes": "python3 << 'EOF'
import json

# Read raw market data
with open('inbox/raw_market_data.json', 'r') as f:
    raw_data = json.load(f)

# Extract metrics
extracted = {
    "report_date": raw_data["report_date"],
    "analysis_id": raw_data["analysis_id"],
    "overall_market_growth": raw_data["overall_market_growth"],
    "total_market_size_bn": raw_data["total_market_size_bn"],
    "sectors": []
}

for sector in raw_data["sectors"]:
    extracted["sectors"].append({
        "name": sector["name"],
        "growth_rate": sector["growth_rate"],
        "market_size_bn": sector["market_size_bn"],
        "key_players": sector["key_players"],
        "sentiment": sector["sentiment"],
        "marker": sector["marker"]
    })

# Write extracted metrics
with open('outbox/extracted_metrics.json', 'w') as f:
    json.dump(extracted, f, indent=2)

# Create summary markdown
summary = f"""# Market Data Metrics Summary

## Report Information
- **Report Date:** {extracted['report_date']}
- **Analysis ID:** {extracted['analysis_id']}

## Overall Market Statistics
- **Total Market Size:** ${extracted['total_market_size_bn']} billion
- **Overall Market Growth:** {extracted['overall_market_growth']}%

## Sector Breakdown
"""

for sector in extracted["sectors"]:
    summary += f"""### {sector['name']}
- **Growth Rate:** {sector['growth_rate']}%
- **Market Size:** ${sector['market_size_bn']} billion
- **Sentiment:** {sector['sentiment']}
- **Key Players:** {', '.join(sector['key_players'])}

"""

with open('outbox/metrics_summary.md', 'w') as f:
    f.write(summary)

print("Data extraction complete!")
EOF
",
